def standard():
    x, p, q, r = symbols('x p q r')
    f = x**3 + p*x**2 + q*x + r
    d1 = diff(f*(1 - x)*(4 - x), x).subs(x, 1) - diff(f*(x - 1)*(4 - x), x).subs(x, 1)
    d4 = diff(f*(x - 1)*(4 - x), x).subs(x, 4) - diff(f*(x - 1)*(x - 4), x).subs(x, 4)
    s = solve([d1, d4, r + 8], [p, q, r])
    return f.subs(s).subs(x, 6)

def unique():
    return [standard()]
